function fallingSquares(positions){
  const coords=new Set();
  for(const[l,size]of positions){coords.add(l);coords.add(l+size-1);}
  const sorted=[...coords].sort((a,b)=>a-b);
  const compress=new Map(sorted.map((v,i)=>[v,i+1]));
  const n=sorted.length;
  const tree=new Array(4*(n+1)).fill(0),lazy=new Array(4*(n+1)).fill(0);
  function pushDown(node){if(lazy[node]>0){tree[2*node]=Math.max(tree[2*node],lazy[node]);lazy[2*node]=Math.max(lazy[2*node],lazy[node]);tree[2*node+1]=Math.max(tree[2*node+1],lazy[node]);lazy[2*node+1]=Math.max(lazy[2*node+1],lazy[node]);lazy[node]=0;}}
  function update(ql,qr,val,node=1,l=1,r=n){if(qr<l||r<ql)return;if(ql<=l&&r<=qr){tree[node]=Math.max(tree[node],val);lazy[node]=Math.max(lazy[node],val);return;}pushDown(node);const mid=(l+r)>>1;update(ql,qr,val,2*node,l,mid);update(ql,qr,val,2*node+1,mid+1,r);tree[node]=Math.max(tree[2*node],tree[2*node+1]);}
  function query(ql,qr,node=1,l=1,r=n){if(qr<l||r<ql)return 0;if(ql<=l&&r<=qr)return tree[node];pushDown(node);const mid=(l+r)>>1;return Math.max(query(ql,qr,2*node,l,mid),query(ql,qr,2*node+1,mid+1,r));}
  const result=[];let maxH=0;
  for(const[l,size]of positions){const cl=compress.get(l),cr=compress.get(l+size-1);const base=query(cl,cr);const nh=base+size;update(cl,cr,nh);maxH=Math.max(maxH,nh);result.push(maxH);}
  return result;
}
const fallingSquaresImpl = fallingSquares;

