function computeHeavyChild(adj, root) {
  const n=adj.length,size=new Array(n).fill(1),heavy=new Array(n).fill(-1);
  const parent=new Array(n).fill(-1);
  const order=[];const visited=new Array(n).fill(false);
  const stack=[root];visited[root]=true;
  while(stack.length){const v=stack.pop();order.push(v);for(const u of adj[v])if(!visited[u]){visited[u]=true;parent[u]=v;stack.push(u);}}
  for(let i=order.length-1;i>=0;i--){
    const v=order[i];
    if(parent[v]!==-1)size[parent[v]]+=size[v];
    let maxS=0;
    for(const u of adj[v])if(u!==parent[v]&&size[u]>maxS){maxS=size[u];heavy[v]=u;}
  }
  return heavy;
}

function countChains(heavy, n) {
  const isHeavyChild=new Set(heavy.filter(h=>h!==-1));
  let chains=0;
  for(let v=0;v<n;v++)if(!isHeavyChild.has(v))chains++;
  return chains;
}

