class LCA {
  constructor(n,adj,root=0){
    this.n=n;this.LOG=Math.ceil(Math.log2(n))+1;
    this.depth=new Array(n).fill(0);
    this.ancestor=Array.from({length:n},()=>new Array(this.LOG).fill(-1));
    const parent=new Array(n).fill(-1);const stack=[root];const visited=new Array(n).fill(false);visited[root]=true;
    while(stack.length){const v=stack.pop();for(const u of adj[v]){if(!visited[u]){visited[u]=true;parent[u]=v;this.depth[u]=this.depth[v]+1;stack.push(u);}}}
    for(let v=0;v<n;v++)this.ancestor[v][0]=parent[v];
    for(let k=1;k<this.LOG;k++)for(let v=0;v<n;v++){const mid=this.ancestor[v][k-1];this.ancestor[v][k]=mid===-1?-1:this.ancestor[mid][k-1];}
  }
  lca(u,v){
    if(this.depth[u]<this.depth[v])[u,v]=[v,u];
    let diff=this.depth[u]-this.depth[v];
    for(let k=0;k<this.LOG;k++)if((diff>>k)&1)u=this.ancestor[u][k];
    if(u===v)return u;
    for(let k=this.LOG-1;k>=0;k--)if(this.ancestor[u][k]!==this.ancestor[v][k]){u=this.ancestor[u][k];v=this.ancestor[v][k];}
    return this.ancestor[u][0];
  }
}

