function height(node){return node?node.height:0;}
function balanceFactor(node){return node?height(node.left)-height(node.right):0;}
function updateHeight(node){node.height=1+Math.max(height(node.left),height(node.right));}
function leftRotate(z){const y=z.right,T2=y.left;y.left=z;z.right=T2;updateHeight(z);updateHeight(y);return y;}
function rightRotate(z){const y=z.left,T3=y.right;y.right=z;z.left=T3;updateHeight(z);updateHeight(y);return y;}
function balance(node){
  updateHeight(node);const bf=balanceFactor(node);
  if(bf>1){if(balanceFactor(node.left)<0)node.left=leftRotate(node.left);return rightRotate(node);}
  if(bf<-1){if(balanceFactor(node.right)>0)node.right=rightRotate(node.right);return leftRotate(node);}
  return node;
}
function avlInsert(node,val){
  if(!node)return new AVLNode(val);
  if(val<node.val)node.left=avlInsert(node.left,val);
  else if(val>node.val)node.right=avlInsert(node.right,val);
  return balance(node);
}

